  AcademicTerm: 'AcademicTerm',
  Course: 'Course',
  CourseAssignment: 'CourseAssignment',
  Schedule: 'Schedule',
  ScheduleSlot: 'ScheduleSlot',
  BreakPolicy: 'BreakPolicy',
